// === Tab: mySketch ===
// 普通にfractすると整数1ごとにグリッドができる。
// これを2本の一次独立なベクトルを使ってやってみるわけ。
// 基本は(0, 1)と(1, 0)でやってるけど・・内積取って座標を算出する感じ。

let myShader;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getHSB(float r, float g, float b){" +
"    vec3 c = vec3(r, g, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
// e1, e2は単位ベクトルでなくていいけど一次独立でないと('ω'乂)ﾀﾞﾒｰ
"vec2 getGrid(vec2 p, vec2 e1, vec2 e2){" +
"  float a = dot(e1, e1);" +
"  float b = dot(e1, e2);" +
"  float c = dot(e2, e2);" +
"  float det = a * c - b * b - b;" +
"  float coeff_x = (c * dot(p, e1) + b * dot(p, e2)) / det;" +
"  float coeff_y = (-b * dot(p, e1) + a * dot(p, e2)) / det;" +
"  return fract(vec2(coeff_x, coeff_y));" +
"}" +
"void main(void){" +
"  vec2 st = gl_FragCoord.xy * 0.1 / min(u_resolution.x, u_resolution.y);" +
"  st *= 2.0;" +
"  float angle = u_time * pi * 0.1;" +
"  float radius = 1.0 + 0.2 * sin(angle * 3.0);" +
"  vec2 e1 = radius * vec2(cos(angle), sin(angle));" +
"  vec2 e2 = radius * vec2(cos(angle + pi / 3.0), sin(angle + pi / 3.0));" +
"  vec2 f = getGrid(st, e1, e2);" +
"  float sat = 0.5 * (f.x + f.y);" +
"  float hue = mod(u_time * 0.07, 1.0);" +
"  gl_FragColor = vec4(getHSB(hue, sat, 1.0 - sat * 0.3), 1.0);" +
"}";

let lapse = 0;    // mouse timer

function setup(){
  createCanvas(1112, 834, WEBGL);
	background(0);
	frameRate(60);
  myShader = createShader(vs, fs);
  shader(myShader);
  //noLoop();
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", millis() / 1000);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

